-- mod-stellar-tarot — the items: one per card, one per board.
--
-- Card N is item 87000 + N, board B is item 87500 + B. The names are the
-- names a player reads; the catalogue keeps the English one of reference.
--
-- The displays are the game's own (Darkmoon cards and decks): nothing to patch
-- in the client for the icons. Item.dbc is another matter -- the client needs
-- a row per item, and the installer merges data/dbc/stellartarot_Item.dbc
-- into its own file.
--
-- USE: every card carries spell 88000 and every board spell 88001, cast on
-- use (trigger 0), no charge consumed by the cast (0): the module intercepts
-- the use server side, studies the item into the account's binder and destroys
-- it itself. See stellar_tarot_07_spells.sql.
--
-- GENERATED by the author's tooling. Regenerable: every block deletes its own
-- range before writing it again.

DELETE FROM `item_template` WHERE `entry` BETWEEN 87001 AND 87699;
DELETE FROM `item_template_locale` WHERE `ID` BETWEEN 87001 AND 87699;
DELETE FROM `item_dbc` WHERE `ID` BETWEEN 87001 AND 87699;
DELETE FROM `item_loot_template` WHERE `Entry` = 87600;

